export interface BlogAuthor {
  name: string;
  bio: string;
  jobTitle: string;
  url: string;
  schemaId: string;
}

export interface BlogCategory {
  slug: string;
  label: string;
  description: string;
}

export interface BlogPost {
  slug: string;
  title: string;
  excerpt: string;
  categorySlug: string;
  date: string;
  readingTime: string;
  /** Path relative to /public, e.g. '/images/courses/hillside.jpg' */
  image?: string;
  /** Describes what the hero picture shows. Falls back to the post title. */
  imageAlt?: string;
  /**
   * Set only on a paid, sponsored article. The post is then labelled Sponsored,
   * bylined "Sponsored by <name>" with no author bio, its JSON-LD author is the
   * sponsor, and links to the sponsor carry rel="sponsored noopener".
   * No sponsored article exists yet.
   */
  sponsor?: { name: string; url: string };
  content: ContentBlock[];
}

export type ContentBlock =
  | { type: 'p'; text: string }
  | { type: 'h2'; text: string }
  | { type: 'h3'; text: string }
  | { type: 'ul'; items: string[] }
  | { type: 'callout'; text: string }
  | { type: 'hr' };

