// Each slug appears once (tests/blog-data.test.mjs checks it). Three slugs used to be
// listed two or three times; the later copies were never shown and have been deleted.
export const BLOG_POSTS: BlogPost[] = ALL_BLOG_POSTS;

export function getPostBySlug(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find((p) => p.slug === slug);
}

// The 154th Open at Royal Birkdale ran from 12 to 19 July 2026 (theopen.com).
const OPEN_2026_LAST_DAY = '2026-07-19';

// Posts outside the 'the-open-2026' category that were written for the build-up to
// The Open and still carry advice for that week. They stay as dated records and show
// the pre-Open note (see showsPreOpenNote).
export const PRE_OPEN_NOTE_SLUGS = new Set<string>([
  'sefton-coast-golf-trip-open-week-2026',
  'sefton-links-may-conditions-2026',
  'sefton-coast-links-june-2026',
  'sefton-coast-july-conditions-2026',
  'sefton-coast-golf-august-2026',
]);

/** True for a post written before The 154th Open that gives advice for Open week. */
export function showsPreOpenNote(post: BlogPost): boolean {
  if (toIso(post.date) >= OPEN_2026_LAST_DAY) return false;
  return post.categorySlug === 'the-open-2026' || PRE_OPEN_NOTE_SLUGS.has(post.slug);
}

export function getPostsByCategory(categorySlug: string): BlogPost[] {
  return [...BLOG_POSTS]
    .filter((p) => p.categorySlug === categorySlug)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

export function getSortedBlogPosts(): BlogPost[] {
  return [...BLOG_POSTS].sort(
    (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime(),
  );
}

function toIso(dateStr: string): string {
  const MONTHS: Record<string, string> = {
    Jan: '01', Feb: '02', Mar: '03', Apr: '04', May: '05', Jun: '06',
    Jul: '07', Aug: '08', Sep: '09', Oct: '10', Nov: '11', Dec: '12',
  };
  const [day, mon, year] = dateStr.split(' ');
  return `${year}-${MONTHS[mon] ?? '01'}-${day.padStart(2, '0')}`;
}

export function getIsoDate(post: BlogPost): string {
  return toIso(post.date);
}
